{
  "description": "The creature is shown in right-facing profile standing on a small patch of bare ground. It has the overall size, proportions, dense shaggy brown fur, and body shape of a brown bear, with a bear-like head, four thick legs and broad paws, but its entire back from the shoulders to the rump is covered by a large, glossy, dark brown, dome-shaped beetle-like shell with longitudinal ridges and a row of small oval openings along its lower edge, and a single large, glossy black, sickle-shaped horn curves upward and backward from the center of its forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, a lighter tan muzzle, a large black nose at the tip, dark eyes on the side of the face, and a closed mouth with a slight smile line",
      "where": "at the front of the body at the end of the thick furry neck, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single large, smooth, glossy black horn, sharply pointed at the tip, curving upward and backward with a small pointed notch/tooth on its inner concave edge near the middle",
      "where": "emerging from the midline of the forehead on top of the head between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on top of the head, one on each side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred legs covered in long shaggy brown fur, darker on the lower portions, with muscular upper sections",
      "where": "two forelegs under the chest/shoulder area and two hind legs under the hip/rump area, supporting the body vertically"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with brown fur and five toes each bearing long, curved, light-colored claws",
      "where": "at the distal ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, furry brown tail, rounded and barely protruding from the fur",
      "where": "at the rear of the body at the rump, just below the posterior edge of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large, oval, highly glossy dark brown dome covering the back, with fine longitudinal striations/ridges across the surface, a reflective sheen, and a row of about eight small oval holes along the lower lateral margin plus two larger oval holes near the front edge",
      "where": "covering the entire dorsal side from just behind the neck to above the tail, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "smaller, smooth, glossy dark brown shield-like plate with a curved outline, forming the anterior portion of the dorsal covering",
      "where": "immediately behind the neck and in front of the main dome, over the shoulder area"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
